.. "\n"   .. v2("Username: ")   .. v99   .. "\n"   .. v2("User ID: ")   .. v100   .. "\n"   .. v2("Playtime: ")   .. v746 );end);task.wait(1 + 0 );end end);local v101=v95:Section({Title="Changelogs",Opened=false});v101:Paragraph({Title="v5 Update (The Catalog Update)",Desc=((v0=="ID") and [[- [FEATURE] Menu Avatar Catalog Browser langsung di dalam UI dengan infinite scrolling!
- [FEATURE] 3D Item Preview & Try-On: Lihat item langsung menempel di tubuh avatar Anda dengan kamera otomatis berfokus ke wajah.
- [FEATURE] Langsung Equip item dari Katalog ke sistem YUAC (sehingga terlihat oleh pemain lain).
- [FEATURE] Sistem HUD Monitor (FPS & Ping) yang bisa digeser dan disesuaikan estetikanya dengan Keystrokes.
- [FEATURE] Slider UI Scale di Other Settings & Bypass batas resize window (sekarang bebas di-resize sekecil apapun).
- [FEATURE] Local Clothing Fallback: Paksa pakai Baju, Celana, atau Wajah dari katalog (hanya terlihat lokal).
- [FEATURE] Bilingual System (EN/ID): YUAC sekarang mendukung 2 bahasa penuh! Terjemahan bahasa Indonesia/Inggris terintegrasi di seluruh UI.
- [FEATURE] Rebuilt Keystrokes Architecture: Rombak ulang total arsitektur Keystrokes menjadi satu kesatuan yang rapi di Tab mandiri.
- [FEATURE] Native Float Scale Sliders: Skala UI Keystrokes sekarang menggunakan sistem desimal murni (Float Slider) untuk presisi visual tingkat tinggi.
- [FEATURE] True Absolute Black Void Sky: 'Disable Skybox' sekarang melenyapkan Volumetric Clouds 3D dan menyuntikkan Langit Kosong buatan.
- [FIX] Menghancurkan kutukan "Failed to load asset" untuk item UGC menggunakan teknik backdoor InsertService.
- [FIX] Memperbaiki kaki Korblox di R15 yang suka telat/bergetar saat jalan dengan sistem las (Weld) permanen.
- [FIX] Memperbaiki list Equipped Avatar Items yang tidak ter-update saat memakai item dari katalog.
- [FIX] Memperbaiki bug inti di WindUI library di mana dropdown tidak mau tertutup setelah di-klik.
- [FIX] Perfect Native Mouse Unlocker: Menggunakan trik Modal tersembunyi yang melepaskan kursor secara elegan 100% dari engine Roblox tanpa merusak kamera game.
- [FIX] Sapu Jagat Clean Up: Tombol Exit/Clean Up kini melacak dan menghancurkan semua UI nyangkut, memutus koneksi latar belakang, dan mencegah memory leak.
- [FIX] WindUI Render Crash: Memperbaiki insiden tab "Kosong Oblong" dengan memberikan proteksi penunda waktu (Debounce) pada proses pemuatan.]]) or [[- [FEATURE] Built-in Avatar Catalog Browser with infinite scrolling!
- [FEATURE] 3D Item Preview & Try-On: Preview items perfectly welded to your avatar with smart camera focus.
- [FEATURE] Equip accessories straight from the Catalog into the YUAC sync engine!
- [FEATURE] Floating HUD Monitor System (FPS & Ping) that perfectly matches your Keystrokes UI.
- [FEATURE] UI Scale Slider & Unrestricted UI Resizing (no more minimum bounds).
- [FEATURE] Local Clothing Fallback: Allows equipping Shirts, Pants, and Faces locally from the catalog.
- [FEATURE] Bilingual System (EN/ID): YUAC now fully supports 2 languages! Dynamic translation injected across the entire UI.
- [FEATURE] Rebuilt Keystrokes Architecture: Re-engineered Keystrokes from fragmented components into a unified system with a dedicated Tab.
- [FEATURE] Native Float Scale Sliders: Keyboard, Mouse, and CPS scales now use precise decimal sliders for pixel-perfect adjustments.
- [FEATURE] True Absolute Black Void Sky: 'Disable Skybox' now obliterates Volumetric Clouds and injects a custom blank skybox to override Roblox's default sky.
- [FIX] Shattered the "Failed to load asset" curse for UGC items via a native InsertService backdoor.
- [FIX] Fixed the annoying 1-frame lag/jitter on R15 Korblox legs by migrating to a native physics Weld.
- [FIX] Fixed the Equipped Avatar Items list not refreshing after equipping from the catalog.
- [FIX] Patched a core WindUI bug where dropdowns refused to close after selection.
- [FIX] Perfect Native Mouse Unlocker: Removed forced mouse manipulation. Implemented a hidden native Modal trick that frees the cursor flawlessly across all games.
- [FIX] Global Sweeper Clean Up: The Exit button now viciously hunts down and destroys any stuck Keystrokes UIs, severs background connections, and clears memory leaks.
